    fr: "Le partenaire est le vendeur responsable de la transaction auprès du client final désigné. Fil One tarifie et facture le compte partenaire à son niveau de cession enregistré\u202f; le partenaire fixe le prix de revente.",
    de: "Der Partner ist gegenüber dem benannten Endkunden Merchant of Record. Fil One bepreist das Partnerkonto nach seiner hinterlegten Einkaufsstufe und stellt ihm die Rechnung; den Wiederverkaufspreis legt der Partner fest.",
    ja: "指定されたエンド顧客に対してはパートナーが販売主体です。Fil One は保存済みの仕切価格帯でパートナーアカウントに価格を設定して請求し、再販価格はパートナーが設定します。",
