  "partner.quote.nothing.referral.description": {
    en: "Your agreement is a referral: Fil One is merchant of record, prices the end client itself and pays commission under your agreement. A partner can only write a quote where the partner is merchant of record, so referral quotes are not yours to create. Register the deal and the Fil One desk quotes it.",
    es: "Su acuerdo es de recomendación: Fil One es el vendedor responsable de la transacción, fija el precio al cliente final y paga la comisión según su acuerdo. Un socio solo puede redactar un presupuesto cuando es el vendedor responsable de la transacción, así que los presupuestos de recomendación no le corresponden. Registre la oportunidad y el equipo de Fil One preparará el presupuesto.",
    fr: "Votre accord est un accord d’apport d’affaires\u00a0: Fil One est le vendeur responsable de la transaction, fixe elle-même le prix pour le client final et verse la commission prévue par votre accord. Un partenaire ne peut établir un devis que s’il est le vendeur responsable de la transaction\u202f; les devis d’apport d’affaires ne relèvent donc pas de vous. Enregistrez l’opportunité et l’équipe Fil One établira le devis.",
    de: "Ihre Vereinbarung ist eine Empfehlungsvereinbarung: Fil One ist Merchant of Record, bepreist den Endkunden selbst und zahlt die Provision gemäß Ihrer Vereinbarung. Ein Partner kann nur dann ein Angebot erstellen, wenn er selbst Merchant of Record ist; Empfehlungsangebote erstellen daher nicht Sie. Registrieren Sie den Deal, dann erstellt das Team von Fil One das Angebot.",
    ja: "貴社の契約は紹介契約です。Fil One が販売主体としてエンド顧客への価格を自ら設定し、契約に基づいてコミッションを支払います。パートナーが見積もりを作成できるのはパートナー自身が販売主体の場合に限られるため、紹介の見積もりは貴社では作成できません。案件を登録すると、Fil One の担当チームが見積もりを作成します。",
    pt: "Seu acordo é de indicação: a Fil One é a vendedora responsável pela transação, define o preço para o cliente final e paga a comissão conforme o seu acordo. O parceiro só pode fazer uma cotação quando é o vendedor responsável pela transação, então as cotações de indicação não cabem a você. Registre a oportunidade e a equipe da Fil One fará a cotação.",
    zh: "您的协议为推荐协议：Fil One 为交易责任商户，自行向终端客户定价，并按您的协议支付佣金。合作伙伴仅在自身为交易责任商户时才能编制报价，因此推荐报价不由您创建。请报备商机，Fil One 团队将为其报价。",
    ar: "اتفاقيتك اتفاقية إحالة: تكون Fil One التاجر المسؤول عن المعاملة، وتسعّر العميل النهائي بنفسها، وتدفع العمولة وفق اتفاقيتك. لا يستطيع الشريك إعداد عرض سعر إلا إذا كان هو التاجر المسؤول عن المعاملة، لذا لا تُنشئ أنت عروض أسعار الإحالة. سجّل الفرصة وسيُعدّ فريق Fil One عرض السعر.",
  },
